Method.Source:
/// <summary>
///  M.essl 11.03.2024
/// </summary>
/// <param name="sender">sender</param>
/// <param name="e">e</param>
[FormControlEventHandler(formControlStr(WHSRFMenuItem, AVAPrinterSetupButton), FormControlEventType::Clicked)]
public static void AVAPrinterSetupButton_OnClicked(FormControl sender, FormControlEventArgs e)
{
    WHSRFMenuItemTable      WHSRFMenuItemTable;
    FormRun                 element =  sender.formRun();
    FormDataSource          WHSRFMenuItemTable_ds  = element.dataSource();

    WHSRFMenuItemTable= WHSRFMenuItemTable_ds.cursor();

    WHSRFMenuItemTable.avaSetupPrinter();

    sender.hasChanged(true);
}
